    before: async (m, { conn, isOwner, isAdmin }) => {
        if (!m.isGroup || !m.chat) return false;

        const chatId = m.chat;
        const cfg = getGroupSettings(chatId);
        const botJid = (conn.user?.id || '').split(':')[0] + '@s.whatsapp.net';

