                        `• *Pengirim :* ${senderTag}\n` +
                        `• *Tipe Pesan :* ${cached.typeLabel || 'Teks'}\n` +
                        `• *Waktu Kirim :* ${sendTime}\n`;

                    if (cached.mediaBuffer) {
