                                image: cached.mediaBuffer,
                                caption: `${infoHeader}\n*Isi Pesan / Caption :*\n${captionText || '_(Tanpa teks)_'}`,
                                mentions: [senderJid]
                            });
                        } else if (mtype === 'videoMessage') {
                            await conn.sendMessage(chatId, {
                                video: cached.mediaBuffer,
                                caption: `${infoHeader}\n*Isi Pesan / Caption :*\n${captionText || '_(Tanpa teks)_'}`,
                                mentions: [senderJid]
                            });
                        } else if (mtype === 'audioMessage') {
                            await conn.sendMessage(chatId, { text: infoHeader, mentions: [senderJid] });
                            await conn.sendMessage(chatId, {
                                audio: cached.mediaBuffer,
                                mimetype: 'audio/mp4',
                                ptt: Boolean(cached.isPtt)
                            });
                        } else if (mtype === 'stickerMessage') {
                            await conn.sendMessage(chatId, { text: infoHeader, mentions: [senderJid] });
                            await conn.sendMessage(chatId, { sticker: cached.mediaBuffer });
                        } else if (mtype === 'documentMessage') {
                            await conn.sendMessage(chatId, {
                                document: cached.mediaBuffer,
                                mimetype: cached.mimetype || 'application/octet-stream',
                                fileName: cached.fileName || 'Dokumen',
                                caption: `${infoHeader}\n*Isi Pesan / Caption :*\n${captionText || '_(Tanpa teks)_'}`,
                                mentions: [senderJid]
                            });
                        }
                    } else {
                        await conn.sendMessage(chatId, {
                            text: `${infoHeader}\n*Isi Pesan :*\n${captionText || '_(Pesan kosong)_'}`,
                            mentions: [senderJid]
                        });
                    }
                }
            }
            return false;
        }

        // B. SIMPAN PESAN AKTIF KE DISK
        const currentMsgId = m.key?.id || m.id;
        if (cfg.antidelete && currentMsgId) {
            const rawMsg = m.message?.ephemeralMessage?.message || m.message || m.msg || {};
            const keys = Object.keys(rawMsg);
            const mtype = keys.find(k => k.endsWith('Message')) || keys[0] || 'conversation';

            const sender = m.key?.participant || m.sender || m.participant;
            const textBody = (m.text || m.body || rawMsg.conversation || rawMsg.extendedTextMessage?.text || rawMsg[mtype]?.caption || '').trim();

            let typeLabel = 'Teks';
            let mediaExt = null;
            let isMedia = false;
            let isPtt = false;

            if (mtype === 'imageMessage') {
                typeLabel = 'Gambar / Foto';
                mediaExt = 'jpg';
                isMedia = true;
            } else if (mtype === 'videoMessage') {
                typeLabel = 'Video';
                mediaExt = 'mp4';
                isMedia = true;
            } else if (mtype === 'audioMessage') {
                typeLabel = rawMsg.audioMessage?.ptt ? 'Voice Note (VN)' : 'Audio';
                mediaExt = 'ogg';
                isMedia = true;
                isPtt = Boolean(rawMsg.audioMessage?.ptt);
            } else if (mtype === 'stickerMessage') {
                typeLabel = 'Stiker';
                mediaExt = 'webp';
                isMedia = true;
            } else if (mtype === 'documentMessage') {
