                return true;
            }
        }

        // F. ANTI-PICTURE
        const isImage = m.mtype === 'imageMessage' || !!m.message?.imageMessage;
        if (cfg.antipicture && isImage) {
            if (botAdmin) {
                registerBotDelete(m.key?.id);
                await conn.sendMessage(chatId, { delete: m.key });
