            spamTracker.set(userKey, recent);

            if (recent.length >= 5) {
                spamTracker.delete(userKey);
                if (botAdmin) {
                    registerBotDelete(m.key?.id);
                    await conn.sendMessage(chatId, { delete: m.key });
                }
                await addWarn(conn, chatId, m.sender, 1, 'Melakukan spam pesan berlebihan', { isOwner, isAdmin });
                return true;
            }
        }

        return false;
    },

